"""ORD_LINE renumbering migration."""

from decimal import Decimal
from typing import Any


def _numeric_line_no(value: Any) -> Decimal:
    """Coerce a legacy LINE_NO to a numeric sort value."""
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove deleted rows and renumber surviving lines within each order."""
    surviving = [
        (str(row.get("ORD_ID", "")), _numeric_line_no(row.get("LINE_NO", "")), index, row)
        for index, row in enumerate(lines)
        if row.get("DEL_FLG", "") != "Y"
    ]
    surviving.sort(key=lambda item: (item[0], item[1], item[2]))

    result: list[dict] = []
    current_order: str | None = None
    new_line_no = 0

    for order_id, _old_line_no, _index, source_row in surviving:
        if order_id != current_order:
            current_order = order_id
            new_line_no = 1
        else:
            new_line_no += 1

        migrated_row = dict(source_row)
        migrated_row["LINE_NO"] = new_line_no
        result.append(migrated_row)

    return result
